# -*- coding: utf-8 -*-
"""Service-area hub, two county hubs, 12 Tier 1 and 3 Tier 2 locality pages. Every page is written from
the place's jurisdiction, flood zone, soil, housing stock and community rules; nothing is a city-name swap."""
from _data import CITIES, TIER1, TIER2, CITY_SERVICE, SERVICES, cs_route, BASE_URL
from _h import cap, sec, p, ul, ol, table, note, faq_block, cta, reviewed, svc_link, city_link, cs_link, link, ext, facts, cards
from templates import lead_form


def local_services(slug):
    xs = [cs_link(c, s, SERVICES[s]["name"]) for c, s in CITY_SERVICE if c == slug]
    return xs


def city_page(slug, title, meta, h1, lede, intro_html, sections, faq, changelog="First publication."):
    c = CITIES[slug]
    body = facts([("Jurisdiction", c["jurisdiction"]), ("Drive from Sarasota", c["drive"]), ("Population", c["population"]), ("Flood zones", c["flood"].split(";")[0])])
    body += intro_html
    for h, html_ in sections:
        body += sec(h, html_)
    body += sec("Local service pages", p(f"Written for {c['name']}, one service each:") + ul(local_services(slug)) +
                p(f'All other services: {link("/concrete/", "concrete")}, {link("/pavers/", "pavers")}.'))
    body += faq_block(faq, f"Questions from {c['name']} homeowners")
    body += sec("Request an estimate in " + c["name"], lead_form(city=c["name"]))
    body += reviewed("September 10, 2026", changelog)
    return {"route": f"/areas/{slug}/", "title": title, "meta_description": meta, "h1": h1, "kicker": f"Service area · {c['county']}", "lede": lede,
            "breadcrumbs": [("Home", "/"), ("Areas", "/areas/"), (c["name"], None)], "body_html": body, "faq": faq,
            "schema": [{"@context": "https://schema.org", "@type": "Place", "name": c["name"], "sameAs": c["wiki"], "geo": {"@type": "GeoCoordinates", "latitude": c["lat"], "longitude": c["lng"]}, "containedInPlace": {"@type": "AdministrativeArea", "name": c["county"]}}]}


# ------------------------------------------------------------------ AREAS HUB
def areas_hub():
    rows1 = [[city_link(c), CITIES[c]["jurisdiction"], f'{CITIES[c]["miles"]} mi · {CITIES[c]["drive"]}', CITIES[c]["population"]] for c in TIER1]
    rows2 = [[city_link(c), CITIES[c]["jurisdiction"], f'{CITIES[c]["miles"]} mi · {CITIES[c]["drive"]}', CITIES[c]["population"]] for c in TIER2]
    body = cap("Which places does Sarasota Concrete serve?",
               "All of Sarasota County, from Longboat Key and the city of Sarasota south through Siesta Key, Palmer Ranch, Osprey, Nokomis, Venice, South Venice, North Port and Englewood, plus the Charlotte County coast inside 40 miles: Port Charlotte, Rotonda West, Placida, Grove City and Cape Haze. Manatee County and south Hillsborough are inside the radius but served through their own local sites.",
               p("Distances are straight-line from downtown Sarasota (27.3364, -82.5307), calculated September 10, 2026; drive times reflect the bridges and the I-75 and US-41 corridors. Population figures are the Florida Office of Economic and Demographic Research estimates for April 1, 2025 for municipalities and the 2020 Census for census-designated places."))
    body += sec("Tier 1: Sarasota County, every service", table(["Locality", "Permit office", "Distance and drive", "Population"], rows1))
    body += sec("Tier 2: Charlotte County coast, four services", p("Pool decks, paver driveways, concrete driveways and concrete repair are scheduled in Charlotte County; other services are quoted case by case.") + table(["Locality", "Permit office", "Distance and drive", "Population"], rows2))
    body += sec("County hubs", cards([("/areas/sarasota-county/", "Sarasota County", "Permits, flood zones, the setback line, turtle lighting, soils, HOAs and seasonality for the whole county."), ("/areas/charlotte-county/", "Charlotte County coast", "What Charlotte permits differently, the canal neighborhoods, Rotonda's deed restrictions and Lemon Bay exposure.")]))
    body += cap("Are Lakewood Ranch and Bradenton covered from this site?",
                "No, and on purpose. Lakewood Ranch, University Park, Whitfield, Bayshore Gardens, Bradenton, Palmetto, Ellenton, Parrish, Myakka City, Cortez and Anna Maria Island are 5 to 20 miles away but sit in Manatee County, where the same provider works through Lakewood Ranch Concrete. Ruskin, Sun City Center, Wimauma, Apollo Beach, Gibsonton and Riverview in south Hillsborough are served the same way.",
                p("Keeping one site per county keeps the permit, flood and community information accurate; a page that tried to cover Manatee's building department and Sarasota's at once would get both half right. Punta Gorda, Arcadia, Tampa, Boca Grande and St. Petersburg are outside the radius or across a bay that turns 30 miles into 90 minutes and aren't covered."))
    body += sec("How the tiers were drawn", p("Tier 1 is every Sarasota County locality with its own permit story or ground story: twelve pages, all services. Tier 2 is the Charlotte County coast inside the radius, three pages, four services, because a 55-minute drive is fair for a pool deck and not for a shed pad. Manatee and Hillsborough localities inside 40 miles are listed but not paged, to keep one site per county and one canonical answer per question."))
    body += sec("Bridges and travel", ul(["Siesta Key: Siesta Drive bridge (north) or Stickney Point bridge (south); both are drawbridges and both back up in season.", "Longboat Key: the John Ringling Causeway and St. Armands Circle from Sarasota, or Cortez Road and the Longboat Pass bridge from Bradenton; a truck and trailer plan the day around the openings.", "Casey Key: the Blackburn Point swing bridge, one lane, weight-limited; deliveries are staged.", "Venice Island: the Venice Avenue, KMI and Circus bridges over the Intracoastal.", "Manasota Key: Manasota Beach Road from Englewood, or Beach Road from the south; the key spans both counties.", "North Port and the Charlotte coast: I-75 to Toledo Blade or River Road, or SR-776 through Englewood."]))
    body += reviewed("September 10, 2026")
    return {"route": "/areas/", "title": "Service Area: Sarasota County & the Charlotte Coast", "meta_description": "Where Sarasota Concrete works: every Sarasota County locality from Longboat Key to Englewood plus Port Charlotte, Rotonda West and Placida, with permit office, drive time, population and why Manatee is served separately.",
            "h1": "Service area: Sarasota County and the Charlotte County coast, 40 miles from Sarasota", "kicker": "Areas",
            "lede": "Fifteen locality pages and two county hubs, each with the permit office, flood zone, soil, housing stock and drive time, so an estimate starts with the right rules.",
            "breadcrumbs": [("Home", "/"), ("Areas", None)], "body_html": body}


# ------------------------------------------------------------------ COUNTY HUBS
def sarasota_county():
    body = facts([("Population", "487,640 (Florida EDR, April 2025); over 570,000 in winter"), ("Permit offices", "County, City of Sarasota, Venice, North Port, Town of Longboat Key"), ("Impervious cap", "50% of an RSF lot (Zoning App. A § 6.5)"), ("Turtle season", "May 1 to October 31")])
    body += cap("What rules apply across unincorporated Sarasota County for hardscape?",
                "Four county codes govern most of it: Chapter 98 and Chapter 74 (work in the right-of-way needs a culvert permit or right-of-way use permit), Chapter 22 Article V (contractors need a county Operating Certificate and Certificate of Competency for regulated trades), Appendix A Zoning § 6.5 (impervious cover capped at 50 percent of an RSF lot, pool decks and pavers included), and Chapter 54 (coastal setback in Article XXII, marine turtle protection in Article XXIII, trees in Article XVIII).",
                p(f'The cities inside the county (Sarasota, Venice, North Port, Longboat Key) run their own building departments; the county handles everything else, including Siesta Key, Casey Key, Osprey, Nokomis, Laurel, South Venice, Englewood north of the county line and the unincorporated neighborhoods east of the city. Each office has a page on the {link("/permits/", "permit hub")}.'))
    body += sec("Permits and portals", table(["Office", "Portal", "Phone", "Page"], [
        ["Sarasota County Building (1001 Sarasota Center Blvd; 4000 S. Tamiami Trail, Venice)", "Accela Citizen Access, building.scgov.net", "(941) 861-5000", link("/permits/sarasota-county/", "County")],
        ["City of Sarasota Development Services", "FTG portal, ftgportal.sarasotafl.gov", "(941) 263-6480 (verify)", link("/permits/city-of-sarasota/", "City")],
        ["City of Venice Building and Engineering", "eTRAKiT, trakit.venicegov.com", "(941) 882-7400 (verify)", link("/permits/venice/", "Venice")],
        ["City of North Port Building Division", "Click2Gov", "(941) 429-7044", link("/permits/north-port/", "North Port")],
        ["Town of Longboat Key Planning, Zoning & Building", "Town portal; 501 Bay Isles Rd", "(941) 316-1999", link("/permits/longboat-key/", "Longboat Key")]],
        "Checked September 10, 2026; phone numbers marked verify were not confirmed on an official page"))
    body += sec("Flood zones, the 50% rule and the setback line",
                p(f'The barrier islands (Longboat Key, Lido and St. Armands, Siesta Key, Casey Key, Manasota Key) and the bayfront are in FEMA Special Flood Hazard Areas: AE across most of the islands and VE on the Gulf-facing rows. The NFIP 50 percent rule limits improvements to a building to half its market value before full flood compliance is triggered; the Sarasota County Property Appraiser explains the calculation (improvement value from the tax roll times 1.2, halved, or a private appraisal) and FEMA guidance excludes site improvements such as driveways, pools and landscaping from the count. Sarasota County\'s Gulf Beach Setback Line (Code Chapter 54, Article XXII) prohibits construction seaward of the line without a coastal setback variance from the County Commission, and pools, spas and pool decks are treated as structures for that purpose. Full explanation on {link("/permits/flood-zones-50-percent-rule/", "flood zones and the 50% rule")}.'))
    body += sec("Sea turtle lighting", p(f'Chapter 54, Article XXIII of the county code and the Town of Longboat Key\'s Chapter 100 require, from May 1 to October 31, that artificial light visible from the beach use long-wavelength (560 nm or more) bulbs in fully shielded, downward-directed fixtures. Article XXV covers the Venice beach area. The county\'s Sea Turtle Protection Program answers questions at (941) 861-5000. Fixture guidance is on {link("/permits/sea-turtle-lighting/", "sea turtle lighting")}.'))
    body += sec("Soils and water table", p("The USDA Natural Resources Conservation Service maps most of the county's flatwoods as Myakka fine sand (Florida's state soil), EauGallie, Immokalee, Oldsmar and Wabasso: very deep, poorly to very poorly drained sands with a seasonal high water table within 10 inches of the surface for two to six months a year. The keys are beach sand and fill over shell. For hardscape this means compacted base in lifts, proof-rolled subgrade, geotextile where sand pumps, and drainage that actually leaves the lot. The Web Soil Survey (websoilsurvey.sc.egov.usda.gov) maps any parcel."))
    body += sec("Salt and storm exposure", p("Ian in September 2022 and Helene and Milton in September and October 2024 pushed surge across the islands; Helene measured 6.68 feet on Longboat Key. Salt reaches concrete and stone from Gulf spray, brackish canal and bay water, and salt-chlorinated pools. The coastal hub covers the mechanisms and the maintenance intervals."))
    body += sec("Communities with architectural review", p("Palmer Ranch and its sub-associations (Prestancia, Turtle Rock, Stoneybrook, Deer Creek, Huntington Pointe, Isles of Sarasota, Sandhill Preserve, Esplanade), Wellen Park and the West Villages (Islandwalk, Grand Palm, Gran Paradiso, Renaissance, Sarasota National), Venetian Golf & River Club, Boca Royale, Plantation, Heron Creek, Skye Ranch, Laurel Oak, The Meadows, Villagewalk, Bay Isles, Longboat Key Club, Country Club Shores and most Siesta Key condominiums require ARC or board approval for driveway, patio and pool deck changes. Guides on " + link("/hoa/", "HOA and ARC") + "."))
    body += sec("Seasonality", p("January through April is the peak for both population and demand; the county's population rises past 570,000 in winter. June through September brings 6 to 9 inches of rain a month and afternoon storms, and many owners are away. Hurricane season runs June 1 to November 30. Scheduling, cure protection and remote project management are all built around that calendar."))
    body += sec("Localities in Sarasota County", ul([f'{city_link(c)}: {CITIES[c]["housing"]}.' for c in TIER1]))
    body += reviewed("September 10, 2026")
    return {"route": "/areas/sarasota-county/", "title": "Sarasota County: Permits, Flood Zones, Soils & HOAs", "meta_description": "Sarasota County hub for concrete and pavers: the five permit offices and portals, the 50% impervious cap, flood zones and the Gulf Beach Setback Line, turtle lighting, Myakka sands, storm history and ARC communities.",
            "h1": "Sarasota County: the rules, the ground and the communities behind every hardscape estimate", "kicker": "County hub",
            "lede": "Five permit offices, one county code, a water table under 10 inches for months, and a coast that floods. This page is the reference the locality pages point back to.",
            "breadcrumbs": [("Home", "/"), ("Areas", "/areas/"), ("Sarasota County", None)], "body_html": body}


def charlotte_county():
    body = facts([("Population", "223,430 (Florida EDR, April 2025)"), ("Permit office", "Community Development, 18500 Murdock Circle, Port Charlotte"), ("Flatwork rule", "All slabs, pavers included, require a permit and inspections"), ("NOC threshold", "$5,000")])
    body += cap("What does Charlotte County require differently from Sarasota County?",
                "Charlotte County permits every piece of residential flatwork, structural or not, pavers included, with a site plan, an Affidavit for Accessory Structures where relevant, and a Notice of Commencement recorded before the first inspection when the contract exceeds $5,000. Fees published on the county's page include a $22 zoning review, a $310 line-and-grade fee (or $90 for right-of-way work) and a building fee of 0.004 times valuation over $50,000.",
                p(f'The county also requires termite treatment for flatwork within a foot of a structure and may require an occupation-of-easement approval from Real Estate Services when pavers cross an easement. A driveway located only in the right-of-way is permitted as a ROW permit instead. Licenses accepted for driveway and slab permits include Local Concrete Masonry. Details and links on {link("/permits/charlotte-county/", "the Charlotte County permit page")}.'))
    body += sec("Localities served in Charlotte County", ul([f'{city_link(c)}: {CITIES[c]["housing"]}.' for c in TIER2] + ["Englewood south of the county line and the Charlotte half of Manasota Key are covered on the " + city_link("englewood", "Englewood page") + ".", "Punta Gorda is 41 miles from Sarasota, outside the radius, and is served through Lakewood Ranch Concrete."]))
    body += sec("Ground and water", p("The Port Charlotte grid was platted by General Development Corporation from the 1950s to the 1980s on Myakka and Immokalee sands with roadside swales for drainage; many lots were never graded to modern standards, so a driveway crossing has to keep the swale flowing. Rotonda West sits inside a canal ring; Placida and Cape Haze are filled waterfront lots on Lemon Bay and Gasparilla Sound. Flood zones are AE along the canals and harbor and AE or VE on the Lemon Bay and Gulf-facing edges."))
    body += sec("Storm history", p("Ian made landfall in Lee County on September 28, 2022 with surge and wind that reached Charlotte Harbor and the Englewood coast; Helene and Milton in 2024 brought surge to Manasota Key and the Cape Haze peninsula. Salt in the base and lifted edge restraint are the common paver findings; slabs that sat under salt water are sounded for voids before anyone resurfaces them."))
    body += sec("Communities", p("Rotonda West Association enforces deed restrictions on driveway and exterior changes across the circle; Riverwood, Heritage Oak Park and the South Gulf Cove community associations review hardscape; Boca Royale and the Cape Haze golf communities have ARC review. Submit the county permit application and the association application in parallel; the association usually wants the permit number."))
    body += reviewed("September 10, 2026")
    return {"route": "/areas/charlotte-county/", "title": "Charlotte County Coast: Permits, Canals & Storm Rules", "meta_description": "Charlotte County hub for pool decks, driveways and repair in Port Charlotte, Rotonda West and Placida: the all-flatwork permit rule, fees, NOC threshold, GDC swales, canal flood zones and storm history.",
            "h1": "The Charlotte County coast: what changes south of the county line", "kicker": "County hub",
            "lede": "Port Charlotte, Rotonda West, Placida, Grove City and Cape Haze, where every slab is permitted, the swales drain the grid, and Lemon Bay sets the flood zone.",
            "breadcrumbs": [("Home", "/"), ("Areas", "/areas/"), ("Charlotte County", None)], "body_html": body}


# ------------------------------------------------------------------ TIER 1 LOCALITIES
def sarasota():
    faq = [("Which neighborhoods are inside Sarasota city limits versus the county?", "Downtown, the Rosemary District, Laurel Park, Gillespie Park, Indian Beach and Sapphire Shores, Arlington Park, Southside Village, Harbor Acres, Bird Key, Lido Key and St. Armands are city. Siesta Key, Gulf Gate Estates, Palmer Ranch, Fruitville, Bee Ridge and The Meadows are unincorporated county. The city's FTG permit portal or the Property Appraiser's map settles a specific address."),
           ("Does the city require a permit to replace a driveway?", "For the apron between the sidewalk and the street, yes: that strip is city right-of-way. For the private portion the city reviews it as flatwork through the FTG portal; confirm the current form with Development Services, because the site could not verify the exact category on the city's page."),
           ("How old are west-of-Trail driveways?", "Many date from the 1950s and 1960s, poured at 3 to 3.5 inches on raw sand with no joints. They've outlived their design and the fix is replacement on a compacted base, not another overlay."),
           ("Is Lido Key in a VE zone?", "The Gulf-facing rows are; most of the interior of Lido and St. Armands is AE. The Property Appraiser's property search shows the zone for any parcel."),
           ("What about the Ringling-era homes?", "Mediterranean Revival houses from the 1920s in Indian Beach, Sapphire Shores and Harbor Acres often have original terrazzo and coquina hardscape; the architectural concrete and stone pages are the right fit, and the city's historic preservation rules apply to designated properties.")]
    intro = cap("What does hardscape work look like inside the City of Sarasota?",
                "A city of 58,279 people (Florida EDR, April 2025) with three markets in one: 1920s to 1960s homes west of the Trail on sand and fill, mid-century ranches east of it, and the bayfront keys (Lido, St. Armands, Bird Key) in AE and VE zones. The City of Sarasota, not the county, issues permits inside the limits, and the apron at the street is city property.",
                p("The city's own permit portal (ftgportal.sarasotafl.gov) handles review; Development Services is the office. Grand oaks are protected by both the city (trunks 4 inches and up) and the county, which shapes where a driveway or walk can go in the older neighborhoods. Impervious cover and setbacks follow the city's zoning code rather than the county's 50 percent RSF rule."))
    sections = [
        ("Neighborhoods and what they need", table(["Area", "Housing", "Typical hardscape work"], [
            ["West of the Trail (Southside Village, Cherokee Park, Harbor Acres)", "1940s to 1960s, heavily renovated", "Driveway replacement, paver entries, honed or marble lanai floors"],
            ["Indian Beach, Sapphire Shores, Bayou Oaks", "1920s Mediterranean Revival to 1950s ranch", "Coquina and terrazzo-compatible walks, architectural concrete, bayfront pool decks in AE"],
            ["Downtown, Rosemary District, Laurel Park, Gillespie Park", "Bungalows, condos, new townhomes", "Small courtyard patios, alley driveways, permeable pavers on tight lots"],
            ["Arlington Park, Alta Vista, Paver Park", "1950s to 1970s block homes", "Driveway tear-outs, lanai slabs, pool deck resurfacing"],
            ["Lido Key, St. Armands, Bird Key", "1950s to 1970s waterfront, rebuilds", "Travertine and marble pool decks, elevated slabs, turtle-compliant lighting on Lido"],
            ["Gulf Gate (city portion) and Southgate", "1960s ranches", "Original driveways failing; see the Gulf Gate page"]], "Sarasota city areas, 2026")),
        ("Ground and water", p("East of US-41 the lots sit on Myakka and EauGallie fine sands with a wet-season water table under 10 inches; base compaction in lifts and positive drainage are the whole game. West of the Trail and on the keys the ground is fill and shell over sand, drains fast, and carries salt. Bird Key and Lido Key are in AE with VE on the Gulf face; Ringling Causeway access means truck timing around the bridge.")),
        ("Rules that bite in the city", ul(["Apron replacement needs a city permit because the strip between sidewalk and curb is city right-of-way.", "Retaining walls over 3.5 feet need a permit.", "Trees with trunks 4 inches and up need a permit to remove or root-prune; walks bend around them.", "Lido Key falls under sea turtle lighting rules from May 1 to October 31.", "Historic districts and designated properties have design review."])),
        ("A worked example", p("A 1958 block ranch in Arlington Park with a 3.5-inch, 480-square-foot driveway cracked into eight pieces and an apron heaved by a live oak root. The scope: remove the driveway and apron, protect the oak's critical root zone with a bridge slab over the root instead of cutting it, 4 inches of compacted base, 4-inch 4,000 PSI fiber concrete with #3 bar, joints at 8 feet, and the apron poured to the city detail under the apron permit. Planning band for that job in September 2026: $6,500 to $9,000.")),
    ]
    return city_page("sarasota", "Concrete & Pavers in Sarasota, FL – City Permits, Keys, Cost", "Concrete and paver work inside the City of Sarasota: which neighborhoods are city vs county, the apron permit rule, Lido and Bird Key flood zones, oak protection, mid-century driveways and a worked example with a 2026 price band.",
                     "Concrete and pavers in the City of Sarasota, from Indian Beach to Bird Key", "The city issues its own permits, owns the apron at the street and protects every oak over 4 inches; the keys add AE and VE zones and turtle lighting.", intro, sections, faq)


def fruitville():
    faq = [("Does The Meadows require approval for a patio extension?", "Yes. The Meadows Community Association reviews exterior changes, and the individual condominium and homeowner associations inside The Meadows have their own review. Submit to the sub-association first; it forwards or requires the master's approval."),
           ("Why do The Meadows and Fruitville behave differently from the keys for drainage?", "The keys are sand and fill that drain fast and carry salt. Fruitville and Bee Ridge sit on Myakka, EauGallie and Immokalee sands with a hardpan layer and a seasonal water table under 10 inches; water sits, the base pumps fines, and slabs settle. Base compaction and drainage matter more here than salt does."),
           ("Which permit office covers Fruitville?", "Sarasota County Building at 1001 Sarasota Center Boulevard, through the Accela portal. The area is unincorporated."),
           ("Are there flood zones inland?", "AE pockets along Phillippi Creek and near the Celery Fields; most lots are X. The Property Appraiser's map shows each parcel."),
           ("Is the Fruitville corridor growing?", "Yes, east toward I-75 and Lorraine Road with new subdivisions on filled land; new-construction driveways and lanai extensions on builder slabs are the common request.")]
    intro = cap("What is hardscape work like in Fruitville, Bee Ridge and The Meadows?",
                "This is unincorporated Sarasota County east of the city, permitted by the county through Accela, on flatwoods sands with a shallow seasonal water table and no salt to speak of. The housing runs from 1950s Sarasota Springs and 1960s Kensington Park to 1970s and 80s The Meadows and 2000s subdivisions along Fruitville Road, so the work is driveway and lanai replacement on settled slabs and extensions on builder-grade concrete.",
                p("The county's rules apply in full: culvert or right-of-way use permit for anything at the road, the 50 percent impervious cap on RSF lots, the county tree ordinance for grand oaks, and the $7,500 residential exemption process for small jobs with documentation."))
    sections = [
        ("Neighborhoods", table(["Area", "Housing", "Typical work"], [["Sarasota Springs, Kensington Park", "1950s to 1960s block homes", "Original driveways at 3.5 in., no joints; replacement on compacted base"], ["The Meadows", "1970s to 80s villas and homes, golf community", "Lanai extensions, paver entries, pool deck resurfacing; master and sub-association review"], ["Bee Ridge, Sarasota Springs east", "1970s to 90s ranches on larger lots", "Slabs and pads, driveway widening, boat and RV pads"], ["Fruitville corridor (Laurel Oak, Oak Ford, newer subdivisions)", "1990s to 2020s", "Builder-slab upgrades, paver driveways, outdoor kitchens; ARC review"]], "Fruitville and Bee Ridge areas")),
        ("Ground and water", p("The USDA maps this area as Myakka, EauGallie and Immokalee fine sands, poorly drained, with a spodic hardpan that keeps water near the surface in the wet season. Concrete poured on raw sand here settles at the garage and cracks across long panels; the fix is 4 to 6 inches of compacted base, proof-rolled subgrade and a slope that gets water to a swale or a drain. Well water is common east of I-75, so irrigation rust on driveways is a regular call.")),
        ("A worked example", p("A 1978 home in The Meadows with a 12-by-24 lanai slab that had settled 3/4 of an inch toward the sliders. The slab was sound but the pitch was wrong, so it came out: a 4-inch compacted limerock base, a new 4-inch slab pitched 1/8 inch per foot to a new floor drain at the cage edge, cage re-anchored. Master and sub-association approvals took three weeks; the county reviewed it as flatwork. Planning band in September 2026: $4,000 to $6,000.")),
    ]
    return city_page("fruitville-bee-ridge", "Concrete & Pavers in Fruitville & Bee Ridge, FL – County Rules", "Driveways, lanai slabs, pads and pavers in Fruitville, Bee Ridge, The Meadows, Kensington Park and Sarasota Springs: county permits via Accela, flatwoods sands with a shallow water table, HOA review and a 2026 worked example.",
                     "Concrete and pavers in Fruitville, Bee Ridge and The Meadows", "Unincorporated east Sarasota: county permits, a water table that sits, 1950s to 2020s housing, and associations that review every extension.", intro, sections, faq)


def gulf_gate():
    faq = [("Why are 1960s Gulf Gate driveways failing now?", "They were poured at 3 to 3.5 inches on raw sand with no control joints and no base, sixty years ago. The sand under them has been pumping fines every wet season since, the slabs have settled at the garage and cracked in the middle, and the overlays some owners added are delaminating. The fix is replacement on a compacted base."),
           ("Is Gulf Gate in the city or the county?", "Gulf Gate Estates and most of South Sarasota are unincorporated county; a strip along US-41 and Gulf Gate Drive is city. The Property Appraiser's map shows which."),
           ("Is Gulf Gate in a flood zone?", "Interior blocks are X; lots toward Little Sarasota Bay and along Phillippi Creek are AE."),
           ("What about the concrete-block homes' pool decks?", "Most are original 1960s to 70s slabs with cool-deck overlays applied in the 1990s. Sounding decides whether a new overlay works or the deck comes out; the resurfacing page has the tests."),
           ("How far is Gulf Gate from Siesta Key?", "A mile across the Stickney Point bridge; the same crew works both, but the rules differ: Gulf Gate is inland county, Siesta is barrier island.")]
    intro = cap("What is the hardscape story in Gulf Gate?",
                "Gulf Gate Estates (10,083 people in the 2020 Census) and South Sarasota are 1960s and 1970s block homes on quarter-acre lots, most still on their original driveway, walk and pool deck. The soil is Myakka fine sand with a shallow water table, the jurisdiction is Sarasota County for most streets, and the demand is driveway replacement, pool deck resurfacing or replacement, and repair.",
                p("The county permits through Accela; anything at the road needs a right-of-way use permit. Interior lots are Zone X; the blocks toward Little Sarasota Bay and Phillippi Creek are AE. There's no master HOA in Gulf Gate Estates, which makes it one of the few places in the area where an owner can change a driveway without an ARC packet."))
    sections = [
        ("What's under the driveways", p("Original Gulf Gate driveways were poured thin on sand that was never compacted. Sixty wet seasons of water moving fines out from under them have left voids at the garage and at the street. Sounding with a hammer finds them; a level shows the drop. Replacing the slab without compacting the base in lifts just restarts the clock.")),
        ("Typical projects", table(["Project", "What's usually found", "Approach"], [["Driveway replacement", "3.5-in. slab, no joints, settled at garage", "Remove, 4 to 6 in. compacted base, 4-in. 4,000 PSI, joints at 8 ft, ROW permit"], ["Pool deck", "1960s slab with a 1990s cool-deck overlay, hollow at the coping", "Sound it; overlay if solid, replace if not"], ["Front walk", "Cracked 3-ft walk, root heave from a 1960s oak", "Reroute or bridge the root; county tree rules"], ["Lanai", "Settled slab pitched toward sliders", "Replace with drain"]], "Gulf Gate patterns")),
        ("A worked example", p("A 1972 home two blocks from Little Sarasota Bay with a 780-square-foot pool deck on Myakka fine sand. The original slab was spalled at the coping and hollow across a third of the deck; an overlay would have failed. The deck came out, 4 inches of base went in, a new 4-inch textured deck was poured to two deck drains, and the cage was re-anchored. Eight working days. September 2026 planning band: $7,500 to $11,000.")),
    ]
    return city_page("gulf-gate", "Concrete & Pavers in Gulf Gate, FL – 1960s Driveways & Decks", "Concrete driveways, pool decks and repair in Gulf Gate Estates and South Sarasota: why 1960s slabs on sand are failing, county permits, no master HOA, Zone X vs AE, and a 2026 worked example.",
                     "Concrete and pavers in Gulf Gate, where the 1960s driveways are due", "Original slabs on uncompacted sand, sixty wet seasons later. County permits, no master HOA, and a mile from Siesta Key's bridge.", intro, sections, faq)


def siesta_key():
    faq = [("What flood zone is most of Siesta Key in?", "AE, with VE along the Gulf-facing rows. Both are Special Flood Hazard Areas; VE adds wave action and the strictest construction rules. The Property Appraiser's map shows the zone and the base flood elevation for any parcel."),
           ("Which office handles permits on Siesta Key: county or city?", "Sarasota County. Siesta Key is unincorporated; the county's Building division and Accela portal handle every permit, and the county's coastal setback and turtle lighting codes apply."),
           ("Does a new pool deck count toward the 50% rule?", "No. FEMA's substantial-improvement guidance and the county's practice exclude site improvements such as pool decks, driveways and landscaping from the calculation; only work on the building counts. The county decides case by case, so the permit application still documents it."),
           ("Can lighting be added to a paver deck on Siesta Key?", "Yes, with long-wavelength amber or red bulbs in fully shielded, downward-directed fixtures wherever the beach can see them, May 1 to October 31 under county code Chapter 54, Article XXIII."),
           ("What did Helene and Milton do to hardscape here?", "Surge pushed water and sand into first floors within 150 yards of the beach and left muddy waterlines 2.5 feet up walls. On hardscape it washed out joint sand, lifted spiked edge restraint, deposited salt in bases and, in places, undermined slabs. The post-storm page has the sequence.")]
    intro = cap("What makes Siesta Key hardscape different?",
                "Everything on the island is in a flood zone, most of it AE and the Gulf rows VE; the Gulf Beach Setback Line runs along the beach; turtle lighting rules apply from May 1 to October 31; and the 2024 surge from Helene and Milton reached most streets. Jurisdiction is Sarasota County. The island had 5,454 year-round residents in 2020 and many times that in season.",
                p("The work is pool decks first (travertine, shellstone, porcelain and concrete pavers over rebuilt bases), then post-storm paver restoration, sealing on an 18-month cycle, and elevated-home slabs and driveways under new construction. Every estimate starts with the FEMA zone and the base flood elevation written on the scope."))
    sections = [
        ("Rules on the island", table(["Rule", "What it means for hardscape", "Page"], [["FEMA AE/VE", "Site improvements outside the 50% calculation; VE limits what goes under an elevated home", link("/permits/flood-zones-50-percent-rule/", "Flood zones")], ["Gulf Beach Setback Line", "Pool decks seaward of the line need a coastal setback variance from the County Commission", link("/permits/flood-zones-50-percent-rule/", "Setback line")], ["Marine Turtle Protection (Ch. 54 Art. XXIII)", "Amber/red shielded fixtures visible from the beach, May 1 to Oct 31", link("/permits/sea-turtle-lighting/", "Turtle lighting")], ["Condominium boards", "Deck replacement phased, reserve-funded, board-approved", link("/hoa/barrier-island-condos/", "Condo guide")]], "Siesta Key hardscape rules")),
        ("Ground, salt and surge", p("The island is quartz sand and fill over shell. It drains fast and carries salt to every surface: Gulf spray on the beach side, bay water on the canals, and salt-chlorinated pools in between. Paver sealer lasts 18 to 24 months here, not 3 years; travertine coping on a salt pool is sealed annually. After a surge the base under a paver field holds salt and may hold voids, so the sequence is drain, sound, rebuild, rinse, reset, then sand and seal.")),
        ("Neighborhoods", table(["Area", "Housing", "Typical work"], [["Siesta Village, Beach Road, Midnight Pass north", "1950s cottages, condos, elevated rebuilds", "Condo pool decks, elevated-home slabs, turtle-compliant lighting"], ["Canal streets (Sabal Drive, Palm Island, Bayou Louise)", "1960s to 80s waterfront homes", "Travertine pool decks, paver driveways, post-storm resets"], ["Crescent Beach, Stickney Point, Turtle Beach", "Condos and 1970s homes", "Board-approved deck replacement, sealing"]], "Siesta Key areas")),
        ("A worked example", p("A 1968 canal home off Midnight Pass Road with a 640-square-foot paver pool deck lifted at the seawall side by the October 2024 surge. After three weeks of drying the field was lifted in sections, the base sounded (two voids), rebuilt in lifts and flushed, a concrete curb replaced the spiked restraint at the seawall, the original travertine was rinsed and reset, polymeric sand installed on a dry day, and sealing scheduled 30 days later. Documented with before-and-after photos for the insurer. Planning band, dated September 2026: $6,000 to $9,500.")),
    ]
    return city_page("siesta-key", "Concrete & Pavers on Siesta Key, FL – Flood Zone, Permits, Cost", "Pool decks, paver restoration and sealing on Siesta Key: AE and VE zones, the 50% rule, the Gulf Beach Setback Line, turtle lighting, county permits, 2024 surge lessons and a worked example with a 2026 price band.",
                     "Concrete and pavers on Siesta Key, where every lot is in a flood zone", "County jurisdiction, AE and VE zones, the setback line, turtle lighting and a coast that surged twice in 2024. Pool decks first, restoration second, sealing every 18 months.", intro, sections, faq)


def palmer_ranch():
    faq = [("What soil is under Palmer Ranch homes?", "Myakka and Oldsmar fine sands, graded and filled during development from the late 1980s on. Fill compacts better than native flatwoods sand, but the wet-season water table is still shallow, so base compaction and drainage decide whether a driveway settles."),
           ("Does Palmer Ranch require ARC approval for a paver driveway?", "Yes, twice in most cases: the sub-association (Prestancia, Turtle Rock, Stoneybrook, Deer Creek and the rest) and, for many changes, the Palmer Ranch Master Property Owners Association. The HOA guide covers the packet."),
           ("Which permit office covers Palmer Ranch?", "Sarasota County, through the Accela portal; Palmer Ranch is unincorporated."),
           ("Why is driveway replacement so common here?", "Homes built from 1990 to 2010 came with builder-grade broom driveways that are now 15 to 35 years old and were poured fast. Settlement at the garage, spalling from sprinklers and cracks across long panels are the usual findings."),
           ("Are pool decks the same story?", "Mostly. Original cool-deck overlays from the 1990s are at end of life; sounding decides overlay versus replacement, and travertine or paver replacement is the common choice.")]
    intro = cap("What is hardscape work like in Palmer Ranch?",
                "Palmer Ranch is a 10,000-acre master-planned community in unincorporated Sarasota County, developed since 1986 under the Palmer Ranch Master Property Owners Association with dozens of sub-associations, each with its own architectural review. Houses date from 1990 to 2010 and are now at driveway and pool deck replacement age.",
                p("The county issues permits; the associations approve materials and colors. Lots are graded fill over Myakka and Oldsmar sands, mostly Zone X with AE along the lakes and preserves. The requests are paver driveways in colors the ARC accepts, concrete driveway replacement, travertine pool decks and lanai extensions."))
    sections = [
        ("Communities and review", table(["Community", "Built", "Review"], [["Prestancia", "1990s", "Prestancia HOA plus master"], ["Turtle Rock", "1990s to 2000s", "Sub-association plus master"], ["Stoneybrook Golf & CC", "1990s", "Sub-association plus master"], ["Deer Creek, Huntington Pointe", "1990s", "Sub-association"], ["Isles of Sarasota, Sandhill Preserve, Esplanade", "2000s to 2010s", "Sub-association plus master; strict paver color lists"]], "Palmer Ranch sub-associations, partial list") + p(f'The {link("/hoa/palmer-ranch/", "Palmer Ranch ARC guide")} explains what goes in the packet and the typical sequence.')),
        ("Ground and water", p("Graded fill over flatwoods sand. Better bearing than native ground, still a shallow water table in the wet season and lakes that set the flood zone on the perimeter lots. Builder driveways were poured with little base; replacement is 4 to 6 inches of compacted base and a 4-inch 4,000 PSI slab with joints at 8 to 10 feet, or vehicular pavers on 6 inches of base.")),
        ("A worked example", p("A 1996 home in Turtle Rock with a 640-square-foot builder driveway cracked at the garage and stained by well-water irrigation. The owner chose pavers: demolition, 6 inches of compacted base in lifts, herringbone field in an ARC-approved tan blend with a charcoal border, concrete curb at the street, sprinkler heads redirected. Sub-association and master approvals took four weeks; county ROW use permit for the apron. Band as of September 2026: $10,000 to $14,000.")),
    ]
    return city_page("palmer-ranch", "Concrete & Pavers in Palmer Ranch, FL – ARC, Driveways, Decks", "Driveway and pool deck replacement in Palmer Ranch: 1990 to 2010 homes at replacement age, master and sub-association ARC review, county permits, graded fill over Myakka sand, and a 2026 worked example.",
                     "Concrete and pavers in Palmer Ranch, where 1990s driveways meet ARC review", "Dozens of sub-associations under one master association, county permits, graded fill over flatwoods sand, and a housing stock built from 1990 to 2010.", intro, sections, faq)


def longboat_key():
    faq = [("How high was the storm surge on Longboat Key during Helene and Milton?", "Helene's surge measured 6.68 feet on Longboat Key in September 2024, flooding ground-floor cottages on Gulf of Mexico Drive with about 3 feet of water; Milton followed two weeks later and pushed the Helene debris piles into other houses. Hardscape on the island was under salt water on both occasions."),
           ("What bridges and travel times connect Sarasota to Longboat Key?", "From Sarasota, the John Ringling Causeway to St. Armands Circle and up Gulf of Mexico Drive: 25 to 40 minutes. From the north, Cortez Road and the Longboat Pass bridge. Both routes have drawbridges; deliveries are timed."),
           ("Does Bay Isles or the Longboat Key Club require architectural review for pavers?", "Yes. Bay Isles Association, the Longboat Key Club communities, Country Club Shores and most condominiums review driveway and deck changes, and the Town requires its own permit on top."),
           ("Does the Town of Longboat Key require a permit for a paver driveway or pool deck?", "The Town's Planning & Zoning division reviews at-grade driveways, decks and patios as exceptions under its zoning criteria, and every permit on a property subject to substantial-improvement review goes through that check. The Town Hall at 501 Bay Isles Road, (941) 316-1999, is the office."),
           ("Which county does Longboat Key belong to?", "Both. The Town straddles the Sarasota-Manatee line (2,663 residents in the Sarasota part and 4,782 in the Manatee part, Florida EDR April 2025) but issues its own permits island-wide, so the county line doesn't change the process.")]
    intro = cap("What is hardscape work like on Longboat Key?",
                "A 10-mile barrier island with its own town government, 7,445 year-round residents split across Sarasota and Manatee counties, AE and VE flood zones end to end, turtle lighting rules under Town Ordinance 2021-01, and a 6.68-foot surge in September 2024. The Town of Longboat Key issues every permit, and community and club associations review most exterior changes.",
                p("Demand is travertine, marble and porcelain pool decks on estate lots, sealed paver driveways, post-storm restoration, and elevated-home slabs under new construction. Sealer life here is 18 to 24 months; coping on salt pools is sealed annually; every base is built to be rinsed and reset after the next surge."))
    sections = [
        ("Town rules", table(["Rule", "What it means", "Page"], [["Town permits island-wide", "One office for both county halves; at-grade driveways, decks and patios reviewed by Planning & Zoning", link("/permits/longboat-key/", "Longboat Key permits")], ["Substantial improvement / damage (Code Ch. 154)", "Every permit on a property in the review is checked against the 50% threshold; site work is excluded from the count but still documented", link("/permits/flood-zones-50-percent-rule/", "Flood zones")], ["Marine Turtle Protection (Ch. 100, Ord. 2021-01)", "Bulbs at 560 nm or longer, fully shielded fixtures, May 1 to Oct 31; Code Enforcement tests bulbs", link("/permits/sea-turtle-lighting/", "Turtle lighting")]], "Longboat Key rules")),
        ("Neighborhoods", table(["Area", "Housing", "Typical work"], [["Bay Isles, Longboat Key Club, Harbourside", "1980s to 2000s estates and villas", "Travertine and marble pool decks, sealed paver driveways, ARC review"], ["Country Club Shores, Sleepy Lagoon, Emerald Harbor", "1960s to 80s canal homes", "Deck replacement after surge, driveway pavers, coping"], ["Longbeach Village (north end)", "Cottages, elevated rebuilds", "Elevated-home slabs, small decks, turtle-compliant lighting"], ["Gulf of Mexico Drive condos", "1970s to 90s", "Board-approved phased deck replacement"]], "Longboat Key areas")),
        ("Ground and salt", p("Beach sand and dredged fill. Bases drain quickly and hold salt after a surge; edge restraint set in sand lifts. The standard here is a concrete curb at every exposed edge, geotextile under the base, a fresh-water flush after any flood, and porcelain or dense concrete pavers around salt pools unless the owner commits to annual travertine sealing.")),
        ("A worked example", p("A 1984 canal home in Country Club Shores with a 900-square-foot travertine pool deck that stood in 2 feet of salt water in October 2024. Insurer photos first, three weeks of drying, then the field was lifted, two voids at the seawall side were filled and compacted, the base was flushed, the travertine rinsed and reset, a concrete curb replaced the plastic restraint, and coping was resealed. Town permit documented the site work against the substantial-damage file. Planning band in September 2026: $8,500 to $13,000.")),
    ]
    return city_page("longboat-key", "Concrete & Pavers on Longboat Key, FL – Town Permits & Flood", "Pool decks, paver driveways, sealing and storm restoration on Longboat Key: Town permits island-wide, substantial-improvement review, Ordinance 2021-01 turtle lighting, the 6.68-foot 2024 surge, and a 2026 worked example.",
                     "Concrete and pavers on Longboat Key, under one town government and two counties", "Town permits for both halves of the island, AE and VE zones end to end, 560 nm lighting, and a coast that stood in salt water twice in 2024.", intro, sections, faq)


def osprey():
    faq = [("Is Osprey inside a city or unincorporated Sarasota County?", "Unincorporated county. Permits go through Sarasota County Building and the Accela portal; the county's coastal setback and turtle lighting codes apply on Casey Key."),
           ("What is the North Casey Key Conservation District?", "A special district created by Florida law (Laws of Fla. ch. 70-937) and enforced by the county under Code Chapter 54, Article XXVI, with additional construction rules on the north end of Casey Key. Hardscape near the beach is reviewed under it."),
           ("Do The Oaks and Southbay require architectural review?", "Yes. The Oaks Club communities and Southbay Yacht & Racquet Club review driveway, deck and lighting changes; Rivendell, Willowbend and Park Trace have HOA review too."),
           ("How do trucks reach Casey Key?", "By the Blackburn Point swing bridge, one lane and weight-limited, or from the south via Albee Road. Deliveries are staged and timed."),
           ("Is Osprey in a flood zone?", "Inland Osprey is mostly X with AE along Little Sarasota Bay and the creeks; Casey Key is AE and VE.")]
    intro = cap("What is hardscape work like in Osprey and on Casey Key?",
                "Osprey (6,729 people in the 2020 Census) is unincorporated county along US-41 between Sarasota and Venice, with The Oaks and Southbay estates on the bay side, 1980s to 2000s neighborhoods inland, and Casey Key, a narrow barrier island in AE and VE zones inside the North Casey Key Conservation District. Sarasota County permits everything.",
                p("Demand is high-end pool decks in travertine, marble and porcelain, paver driveways, and on Casey Key the full coastal set: setback line, turtle lighting, salt and surge restoration. Access to the key is by a one-lane swing bridge, which shapes how a job is staged."))
    sections = [
        ("Neighborhoods", table(["Area", "Housing", "Typical work"], [["The Oaks (Bayside, Clubside), Southbay Yacht & Racquet Club", "1980s to 2000s estates, bayfront", "Travertine and marble pool decks, sealed paver driveways, ARC review"], ["Rivendell, Willowbend, Park Trace, Sorrento Woods", "1990s to 2000s", "Builder driveway upgrades to pavers, lanai extensions"], ["Casey Key", "Gulf-to-bay estates, cottages", "VE-zone decks, setback variances, turtle lighting, surge resets"], ["Bay Street, Osprey village", "1950s to 70s", "Driveway and walk replacement"]], "Osprey areas")),
        ("Ground and rules", p("Inland lots are Myakka fine sand; the key is beach sand and fill. County rules apply: right-of-way permits at the road, the 50 percent impervious cap on RSF lots, the coastal setback code and the turtle lighting article on Casey Key, and the conservation district's construction rules on the north end. Oscar Scherer State Park and the Legacy Trail border the area; nothing changes for hardscape, but access roads are shared with trail traffic.")),
        ("A worked example", p("A 2004 home in Rivendell with a 560-square-foot builder pool deck under a cage, spalled at the coping from a salt-chlorinated pool. Sounding found the slab solid, so the deck stayed: loose paste removed, coping replaced in travertine bullnose sealed with a penetrating product, and a light knockdown overlay across the field. HOA approval in two weeks; no county permit was needed for the overlay. September 2026 planning band: $5,500 to $8,000.")),
    ]
    return city_page("osprey", "Concrete & Pavers in Osprey & Casey Key, FL – Permits & Cost", "Pool decks, travertine, paver driveways and driveways in Osprey and on Casey Key: county permits, The Oaks and Southbay ARC review, the Casey Key conservation district, VE zones, swing-bridge staging and a 2026 worked example.",
                     "Concrete and pavers in Osprey and on Casey Key", "Bayfront estates, 1990s neighborhoods and a barrier island reached by a one-lane swing bridge, all permitted by Sarasota County.", intro, sections, faq)


